-- public schema：所有 SECURITY DEFINER、可被 anon 或 authenticated 執行的函式（不含觸發器函式；觸發器函式無法以 RPC 直接呼叫）
-- 唯讀；只有 SELECT、不以 WITH 開頭。suggest 欄為本機調查建議（DONE＝前幾批已處理；A＝收回 PUBLIC/anon/authenticated；A-anon＝只收回 PUBLIC/anon；B＝要加檢查；C＝維持；NEW＝不在本機清單、需另查）
-- 欄位 id_check／writes／sensitive 為關鍵字推測，僅供排序參考，以人工判讀為準
SELECT p.oid::regprocedure::text AS func,
       pg_get_function_result(p.oid) AS returns,
       has_function_privilege('anon', p.oid, 'EXECUTE') AS anon_exec,
       has_function_privilege('authenticated', p.oid, 'EXECUTE') AS auth_exec,
       EXISTS (SELECT 1 FROM aclexplode(COALESCE(p.proacl, acldefault('f', p.proowner))) a WHERE a.grantee = 0 AND a.privilege_type = 'EXECUTE') AS has_public,
       (p.prosrc ~* '(auth\.uid\(\)|auth\.role\(\)|_assert|is_super_admin|is_hotel_admin_of|is_admin_or_super|user_has_role|staff_can_|has_role|require_hq|can_view|team_onboarding_can)') AS id_check,
       (p.prosrc ~* '\m(insert|update|delete)\M' OR p.prosrc ~* '(create_secret|update_secret|set_config)') AS writes,
       (pg_get_function_result(p.oid) || ' ' || p.prosrc) ~* '(email|phone|guest_name|display_name|secret|token|password|api_key|webhook|decrypted|prosrc|functiondef|line_user|amount|price|revenue)' AS sensitive,
       CASE
         WHEN p.proname IN ('_hotelnabe_enqueue_days', 'acquire_group_buy_payment_hold', 'bulk_upsert_room_inventory_pricing', 'cleanup_old_error_logs', 'cleanup_old_monitoring_logs', 'consume_trip_product_stock', 'convert_group_buy_payment_draft', 'delete_group_buy_campaign', 'gbp_save_accommodation_oauth_client_secret', 'gbp_vault_delete', 'import_ryoan_order_bypass', 'increment_member_push_badge', 'recalc_course_profit_payouts', 'scan_stuck_group_buy_paid_drafts', 'seed_app_review_account', 'verify_accommodation_ai_api_key', 'verify_accommodation_api_key', 'verify_owlting_service_account', 'update_order_with_context', 'ensure_trip_share_slug') THEN 'DONE'
         WHEN p.proname IN ('gbp_vault_get', 'gbp_vault_set', 'get_rpc_contract', 'claim_hotelnabe_ari_push_batch', 'calc_team_commission_price', 'apply_ota_modification_v1', '_rls_test_list_member_policies', 'sync_am_hotel_admin', '_am_can_be_responsible', '_am_collab_accommodation_ids', '_am_collab_user_ids', '_am_end_responsible', '_am_refresh_user', '_am_sync_profile_arrays', 'ai_metric_clean_events', 'ai_metric_excluded_emails', 'ai_metric_excluded_line_ids', 'ai_metric_excluded_order_ids', 'ai_metric_excluded_sessions', 'group_buy_campaign_delete_precheck', 'pricing_v2_clean_season_tiers', 'pricing_v2_on_group_member_change', 'pricing_v2_on_holiday_change', 'pricing_v2_rebuild_pdp', 'pricing_v2_recompute_code_scope', 'wizard_precheck_core', 'resolve_template_night_price', 'resolve_pricing_template_by_numeric_code', 'resolve_room_type_by_numeric_code', 'classify_day_tier', 'get_group_buy_adjusted_inventory_batch') THEN 'A'
         WHEN p.proname IN ('get_ai_ops_metrics', 'get_franchise_external_member_ids', 'get_all_order_sources', 'ai_metric_booking_order_sources', 'course_profit_month_locked', 'gbp_platform_ready', 'am_manages_accommodation', 'is_am_team', 'can_unlock_paid_order_discount') THEN 'A-anon'
         WHEN p.proname IN ('list_orphan_kol_discount_codes', 'check_discount_code_conflict', 'get_team_role_members', 'get_staff_module_permission', 'count_kol_reciprocal_orders', 'validate_platform_coupon') THEN 'B'
         WHEN p.proname IN ('_hotelnabe_should_sync', 'admin_delete_order', 'ai_metric_addon_breakdown', 'ai_metric_booking_conversion', 'ai_metric_dashboard', 'ai_metric_remarketing_breakdown', 'ai_metric_require_hq', 'ai_metric_trip_breakdown', 'apply_template_to_user', 'attach_trip_products_to_recent_order', 'calculate_room_remaining', 'can_fix_pricing_rule_date', 'can_manage_scout_discount_codes', 'can_view_user_roles', 'change_order_dates', 'check_exclusive_room_booking', 'check_kol_inventory', 'check_rls_enabled', 'clear_order_room_pricing_template', 'course_profit_payout_period_locked', 'current_user_accommodation_ids', 'delete_package_season', 'delete_pricing_template_group', 'evaluate_discount_code', 'generate_order_number', 'get_adjusted_room_inventory', 'get_adjusted_room_inventory_batch', 'get_amenity_daily_usage', 'get_analytics_summary', 'get_dates_with_active_orders', 'get_discount_code_secrets', 'get_public_discount_code_info', 'get_sales_service_analytics', 'get_user_accommodations', 'hq_ai_booking_demo_get', 'hq_ai_booking_demo_put', 'hq_shared_demo_can_read', 'hq_shared_demo_get', 'hq_shared_demo_put', 'is_admin', 'is_admin_or_super', 'is_hotel_admin_of', 'is_sales_role', 'is_super_admin', 'is_team_admin', 'is_team_inviter', 'is_team_salary_manager', 'is_user_admin', 'list_kol_quota_audit_logs', 'list_kol_rate_audit_logs', 'list_kol_reciprocal_orders', 'pricing_rule_min_month', 'pricing_v2_assert_can_edit', 'rebuild_package_date_prices', 'resolve_change_actor', 'save_package_season', 'save_package_tier_prices', 'save_pricing_template_group', 'set_day_tier_overrides', 'set_discount_code_template_groups', 'set_order_change_context', 'set_pricing_template_group_members', 'staff_can_edit_module', 'staff_can_edit_module_for_room_type', 'staff_can_view_module', 'sync_order_rooms_v1', 'team_cron_health', 'team_cron_history', 'team_onboarding_am_members', 'team_onboarding_can_assign_am', 'team_onboarding_can_view', 'team_onboarding_overview', 'team_set_am_not_required', 'team_set_responsible_am', 'update_kol_quota_config', 'update_order_referral_code_v1', 'update_team_order_marketing_info', 'upsert_customer_for_order', 'upsert_owlting_credentials', 'user_can_access_accommodation', 'user_has_access_to_accommodation', 'user_has_any_team_role', 'user_has_role', 'user_has_storage_access', 'user_has_team_role', 'validate_discount_code', 'wizard_apply_season_prices', 'wizard_assert_access', 'wizard_open_inventory', 'wizard_precheck', 'wizard_precheck_redact', 'wizard_preview_season_prices', 'wizard_return', 'wizard_save_basic_info', 'wizard_save_package', 'wizard_save_room_type', 'wizard_season_plan', 'wizard_submit') THEN 'C'
         ELSE 'NEW'
       END AS suggest
FROM pg_proc p
WHERE p.pronamespace = 'public'::regnamespace AND p.prosecdef AND p.prokind = 'f' AND p.prorettype <> 'trigger'::regtype
  AND (has_function_privilege('anon', p.oid, 'EXECUTE') OR has_function_privilege('authenticated', p.oid, 'EXECUTE'))
ORDER BY CASE WHEN has_function_privilege('anon', p.oid, 'EXECUTE') THEN 0 ELSE 1 END, 9, 1;
